<script setup lang="ts">
import { shallowRef,onMounted,onBeforeUnmount } from 'vue';
import departure from '../../../shared/assets/between-dimensions-final.png';
const props=defineProps<{destination:string;celestial:boolean;sanctuary:boolean}>();
const emit=defineEmits<{done:[]}>();
const running=shallowRef(false);let timer:ReturnType<typeof setTimeout>|undefined;let disposed=false;
const stars=Array.from({length:120},(_,i)=>({left:`${(i*73.17+11)%100}%`,top:`${(i*37.71+3)%100}%`,width:`${i%5===0?3:1.5}px`,height:`${i%5===0?3:1.5}px`,animationDelay:`${i%9*.035}s`,opacity:.25+(i%5)*.12}));
function done(){disposed=true;clearTimeout(timer);emit('done')}
onMounted(async()=>{await Promise.all([departure,props.destination].filter(Boolean).map(src=>new Promise<void>(resolve=>{const image=new Image();image.onload=()=>resolve();image.onerror=()=>resolve();image.src=src})));if(disposed)return;running.value=true;timer=setTimeout(done,5700)});
onBeforeUnmount(()=>{disposed=true;clearTimeout(timer)});
</script>
<template>
 <div class="arrival" :class="{running,sanctuary}" aria-label="Ascending to the Tree of Wisdom">
  <div class="arrival-space"></div><img class="departure" :src="departure" alt=""><div class="clouds clouds-one"></div><div class="clouds clouds-two"></div>
  <div class="arrival-stars"><i v-for="(style,i) in stars" :key="i" :style="style"></i></div>
  <div v-if="!celestial" class="destination"><img :src="destination" alt=""></div>
  <div v-else class="celestial-destination">✧</div>
  <div class="arrival-veil"></div><p class="arrival-title">Tree of Wisdom</p>
  <button class="skip-arrival" @click="done">Skip ↗</button><span v-if="!running" class="arrival-loading">One quiet moment…</span>
 </div>
</template>
