 ease-in-out both}.running .arrival-stars{animation:rise-stars 5.7s ease-out both}.running .destination{animation:arrive-tree 2s 3.6s ease-out both}.running .celestial-destination{animation:arrive-symbol 2s 3.5s both}.running .arrival-title{animation:arrival-name 3.2s 1.9s both}.running{animation:finish-arrival .5s 5.2s both}@keyframes leave-world{0%{transform:translateY(0) scale(1);opacity:1}35%{opacity:1}100%{transform:translateY(80%) scale(1.17);opacity:0}}@keyframes pass-clouds{0%{transform:translateY(-30%);opacity:0}25%{opacity:.8}60%{opacity:.65}100%{transform:translateY(55%);opacity:0}}@keyframes rise-stars{0%,10%{opacity:0;transform:translateY(-8%)}40%{opacity:1}75%{opacity:1}100%{opacity:.1;transform:translateY(34%)}}@keyframes arrive-tree{to{opacity:1;transform:scale(1)}}@keyframes arrive-symbol{0%{opacity:0;transform:scale(.4)}50%{opacity:.65}100%{opacity:0;transform:scale(1.3)}}@keyframes arrival-name{0%{opacity:0;transform:translateY(10px)}25%,60%{opacity:1;transform:translateY(0)}100%{opacity:0;transform:translateY(-8px)}}@keyframes finish-arrival{to{opacity:0;pointer-events:none}}@media(prefers-reduced-motion:reduce){.arrival *{animation:none!important}.departure,.clouds,.arrival-stars,.arrival-title{display:none}.arrival{animation:none!important}.destination{opacity:1;transform:none}.arrival-loading{display:none}}
